using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ValidateDressing{
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const string A="Assets/Afrer_Seconds/";
 public static object Run(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");EditorSceneManager.OpenScene(A+"01.Scenes/Stage/Level_B5_Circular.unity");var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular"));var art=root.transform.Find("B5_Art_C01_T01");Physics.SyncTransforms();var data=JObject.Parse(File.ReadAllText(R+"/Docs/도면/원형공동/facility_layout.json"));var floor=data["floors"].Single(f=>(string)f["id"]=="B5");var blocks=new List<object>();int samples=0;
  foreach(var key in new[]{"route","alternate"}){var ps=floor[key].ToArray();for(int i=1;i<ps.Length;i++){var a=new Vector3((float)ps[i-1][0],-82,-(float)ps[i-1][1]);var b=new Vector3((float)ps[i][0],-82,-(float)ps[i][1]);int n=Math.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/.25f));for(int j=0;j<=n;j++){var p=Vector3.Lerp(a,b,(float)j/n);samples++;var hits=Physics.OverlapCapsule(p+Vector3.up*.34f,p+Vector3.up*1.48f,.27f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root.transform)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0)blocks.Add(new{p=p.ToString(),hits=hits.Select(c=>c.name).Distinct().ToArray()});}}}
  var overlaps=new List<object>();foreach(Transform g in art){var box=g.GetComponent<BoxCollider>();if(!box)continue;foreach(var c in Physics.OverlapBox(box.bounds.center,box.bounds.extents,g.rotation,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=box&&c.transform.IsChildOf(root.transform)&&!c.name.Contains("Floor"))){Vector3 dir;float depth;if(Physics.ComputePenetration(box,box.transform.position,box.transform.rotation,c,c.transform.position,c.transform.rotation,out dir,out depth)&&depth>.035f)overlaps.Add(new{name=g.name,other=c.name,depth});}}
  var missing=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>!f.sharedMesh).Select(f=>f.name).ToArray();var materialMissing=art.GetComponentsInChildren<Renderer>(true).Where(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>r.name).ToArray();
  var lods=art.GetComponentsInChildren<LODGroup>().Select(l=>new{name=l.name,levels=l.GetLODs().Select(x=>x.renderers.Length).ToArray()}).ToArray();
  var result=new{scene=SceneManager.GetActiveScene().path,placements=art.childCount,routeSamples=samples,blocked=blocks,propOverlaps=overlaps,missingMeshes=missing,missingMaterials=materialMissing,lods,trianglesAllLods=art.GetComponentsInChildren<MeshFilter>(true).Sum(f=>f.sharedMesh?f.sharedMesh.triangles.Length/3:0),newLights=art.GetComponentsInChildren<Light>().Length};
  File.WriteAllText(R+"/Docs/검수/2026-11-06_CircularDressing/validation.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Bake(){var s=SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Saved edit scene required");var actor=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var rr=actor.GetComponentsInChildren<Renderer>();var was=rr.Select(r=>r.enabled).ToArray();foreach(var r in rr)r.enabled=false;int count=0;
  try{foreach(var p in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>()).Where(p=>p.name.Contains("C01")||p.name.Contains("C02"))){string file=A+"05.Model/Environment/B5/Textures/CFD_Reflection_"+p.name+".exr";if(!Lightmapping.BakeReflectionProbe(p,file))throw new Exception("Bake failed");AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);count++;}}finally{for(int i=0;i<rr.Length;i++)rr[i].enabled=was[i];}EditorSceneManager.SaveScene(s);return new{baked=count};}
}
